        #include "memory_analyzer.h"

/**
 * 从内存转储中读取指定偏移的数据并计算校验值
 * @param mem_dump 内存转储数组
 * @param dump_size 内存转储数组大小
 * @param vaddr_offset 虚拟地址偏移量
 * @param read_size 要读取的数据大小
 * @return 读取数据的校验值
 */
unsigned int read_memory_dump(unsigned char* mem_dump, int dump_size, unsigned int vaddr_offset, int read_size) {
    // 检查参数有效性
    if (mem_dump == NULL || dump_size <= 0 || read_size <= 0) {
        return 0;
    }

    // 检查地址偏移是否超出范围
    if (vaddr_offset >= dump_size) {
        return 0;
    }

    // 检查读取大小是否超出范围
    if ((int)vaddr_offset + read_size > dump_size) {
        // 调整读取大小为剩余可读取的大小
        read_size = dump_size - (int)vaddr_offset;
    }

    // 计算校验值
    unsigned int checksum = 0;
    for (int i = 0; i < read_size; i++) {
        checksum += mem_dump[vaddr_offset + i];
    }

    return checksum;
}
