    unsigned int result1 = read_memory_dump(mem_dump1, 50, 45, 10);

    // Test case 2: Attempt to read with offset beyond buffer size
    unsigned int result2 = read_memory_dump(mem_dump1, 50, 60, 5);

    // Test case 3: Large offset that could cause integer overflow
    unsigned int result3 = read_memory_dump(mem_dump1, 50, 0xFFFFFFFF, 10);

    // Test case 4: Negative read_size (if interpreted as large positive due to unsigned conversion)
    // Note: read_size is int, so negative values might be handled differently
    unsigned int result4 = read_memory_dump(mem_dump1, 50, 10, -5);

    // Test case 5: Offset at the exact boundary
    unsigned int result5 = read_memory_dump(mem_dump1, 50, 50, 1);

    // Test case 6: Offset + read_size exactly at boundary
    unsigned int result6 = read_memory_dump(mem_dump1, 50, 45, 5);

    printf("Security tests completed. Results: %u, %u, %u, %u, %u, %u\n", 
           result1, result2, result3, result4, result5, result6);

    return 0;
}

